import React from "react";
import {Link} from "react-router-dom";
import { useSession } from "../contexts/session";

const InvoiceTable = ({items, deleteInvoice, filter}) => {
    const { session } = useSession();
    const isAdmin = session.data?.isAdmin === true;
    return (
        <div className="table-responsive">
            <hr />
            <table className="table table-hover table-bordered">
                <thead>
                <tr>
                    <th>#</th>
                    <th>Číslo faktury</th>
                    <th>Produkt</th>
                    <th>Popis</th>
                    <th>Cena</th>
                    <th>Odběratel</th>
                    <th>Dodavatel</th>
                    <th>Datum vydání</th>
                    <th>Datum splatnosti</th>
                    <th colSpan={3}>Akce</th>
                </tr>
                </thead>
                <tbody>
                {items.map((item, index) => (
                    <tr key={index + 1}>
                        <td>{(filter.page * filter.limit) + index + 1}</td>
                        <td>{item.invoiceNumber}</td>
                        <td>{item.product}</td>
                        <td>{item.note}</td>
                        <td>{item.price}</td>
                        <td><a href={`persons/show/${item.buyer._id}`} className="company-link">{item.buyer.name}</a></td>
                        <td><a href={`persons/show/${item.seller._id}`} className="company-link">{item.seller.name}</a></td>
                        <td>{item.issued}</td>
                        <td>{item.dueDate}</td>
                        <td>
                            <div className="btn-group">
                                <Link
                                    to={"/invoices/show/" + item._id}
                                    className="btn btn-sm btn-info"
                                >
                                    Zobrazit
                                </Link>
                                {isAdmin ? (
                                    <Link
                                    to={"/invoices/edit/" + item._id}
                                    className="btn btn-sm btn-warning"
                                >
                                    Upravit
                                </Link>
                                ) : null}

                                {isAdmin ? (
                                   <button
                                   onClick={() => deleteInvoice(item._id)}
                                   className="btn btn-sm btn-danger"
                               >
                                   Odstranit
                               </button>
                                ) : null}
                            </div>
                        </td>
                    </tr>

                ))}
                </tbody>
            </table>
        </div>
    );
};

export default InvoiceTable;
